                  "text": "The original instructions can stabilize passages without forcing every habitat into one past state. Galactic chose a dangerous alternative.",
                  "id": "delta.b.amendment.after.original-001",
                  "speakerId": "narrator",
                  "delivery": "Narration; observe rather than explain the emotion.",
                  "voiceId": "delta.b.amendment.after.original-001"
