      "outro": [
        {
          "speaker": "Narrator",
          "text": "Celebi remembers guiding the final evacuees. Maren confirms it stayed until the boats crossed.",
          "id": "delta.outro.original-001",
          "speakerId": "narrator",
          "delivery": "Narration; observe rather than explain the emotion.",
          "voiceId": "delta.outro.original-001"
        },
        {
          "speaker": "Maren",
          "text": "You stayed long enough.",
          "id": "delta.outro.original-002",
          "speakerId": "maren",
          "delivery": "Conversational; respond to the preceding line.",
          "voiceId": "delta.outro.original-002"
        },
        {
          "speaker": "Narrator",
          "text": "Dragonite opens a route to guardians who recognize the disturbance. A controlled message goes back to Edda: We found them. The bell still rings.",
          "id": "delta.outro.original-003",
          "speakerId": "narrator",
          "delivery": "Narration; observe rather than explain the emotion.",
          "voiceId": "delta.outro.original-003"
        },
        {
          "speaker": "Celebi’s journal",
          "text": "Today I fixed something. It did not have to become what it was before.",
          "id": "delta.outro.original-004",
          "speakerId": "celebi",
          "delivery": "Private journal; reflective, not declaimed.",
          "voiceId": "delta.outro.original-004"
        },
        {
          "id": "delta.maren-reply.01",
          "speaker": "Maren",
          "text": "Give Edda this reply. Tell her my M has not improved.",
          "delivery": "relief; a familiar joke sent across distance",
          "speakerId": "maren",
          "voiceId": "delta.maren-reply.01"
        },
        {
          "id": "delta.maren-reply.02",
          "speaker": "You",
          "text": "Sela is still saving your ferry coin.",
          "delivery": "relief; a familiar joke sent across distance",
          "speakerId": "player",
          "voiceId": "delta.maren-reply.02"
        },
        {
          "id": "delta.maren-reply.03",
          "speaker": "Maren",
          "text": "Tell her to buy the hat. I shall be furious if she chooses a sensible one.",
          "delivery": "relief; a familiar joke sent across distance",
          "speakerId": "maren",
          "voiceId": "delta.maren-reply.03"
        },
        {
          "id": "delta.maren-reply.04",
          "speaker": "Celebi",
          "text": "Everyone remembers such small things.",
          "delivery": "relief; a familiar joke sent across distance",
          "speakerId": "celebi",
          "voiceId": "delta.maren-reply.04"
        },
        {
          "id": "delta.maren-reply.05",
          "speaker": "Maren",
          "text": "That is most of knowing someone, dear.",
          "delivery": "relief; a familiar joke sent across distance",
          "speakerId": "maren",
          "voiceId": "delta.maren-reply.05"
        }
      ],
