              "opponent": "Anwen",
              "deck": "truth",
              "tip": "Develop a second attacker, read the opposing board, and preserve resources for the next turn.",
              "before": [
                {
                  "speaker": "Celebi",
                  "text": "We came all this way.",
                  "id": "watchers.a.closed.brief.original-001",
                  "speakerId": "celebi",
                  "delivery": "Conversational; respond to the preceding line.",
                  "voiceId": "watchers.a.closed.brief.original-001"
                },
                {
                  "speaker": "Anwen",
                  "text": "Resting does not abandon the reason you came. Prepare first.",
                  "id": "watchers.a.closed.brief.original-002",
                  "speakerId": "anwen",
                  "delivery": "Conversational; respond to the preceding line.",
                  "voiceId": "watchers.a.closed.brief.original-002"
                }
              ],
              "after": [
                {
                  "speaker": "Narrator",
                  "text": "You agree on a signal: either companion can pause an overwhelming memory. Recovering the past remains Celebi’s choice.",
                  "id": "watchers.a.closed.after.original-001",
                  "speakerId": "narrator",
                  "delivery": "Narration; observe rather than explain the emotion.",
                  "voiceId": "watchers.a.closed.after.original-001"
                }
              ]
