          "text": "Closing one channel transfers the strain. Several must be supported at the same time.",
          "id": "darkest.outro.original-001",
          "speakerId": "vale",
          "delivery": "Conversational; respond to the preceding line.",
          "voiceId": "darkest.outro.original-001"
